import json
import collections

# Retrieve input parameters
map_id = input_data['map_id']
start_x = int(input_data['start_x'])
start_y = int(input_data['start_y'])
target_x = int(input_data['target_x'])
target_y = int(input_data['target_y'])

grid_width = input_data.get('grid_width')
grid_height = input_data.get('grid_height')

# Determine default dimensions if not specified
if grid_width is None or grid_width == 0:
    if map_id.startswith("0_2"): # Silph Co floors
        grid_width = 30
    else:
        grid_width = 100

if grid_height is None or grid_height == 0:
    if map_id.startswith("0_2"): # Silph Co floors
        grid_height = 20
    else:
        grid_height = 100

extra_impassable_raw = input_data.get('extra_impassable') or []
impassable = set()
for tile in extra_impassable_raw:
    if tile and 'x' in tile and 'y' in tile:
        impassable.add((int(tile['x']), int(tile['y'])))

queue = collections.deque([(start_x, start_y, [])])
visited = set([(start_x, start_y)])

found_path = None
while queue:
    cx, cy, path = queue.popleft()
    if (cx, cy) == (target_x, target_y):
        found_path = path
        break

    for dx, dy, move in [(0, -1, "Up"), (0, 1, "Down"), (-1, 0, "Left"), (1, 0, "Right")]:
        nx, ny = cx + dx, cy + dy
        if 0 <= nx < grid_width and 0 <= ny < grid_height:
            if (nx, ny) not in impassable:
                if (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append((nx, ny, path + [move]))

if found_path is not None:
    print(json.dumps(found_path))
else:
    print(json.dumps([]))
